import {escapeHtml as esc} from './agent-view.js';
import {LIVE_STATUSES} from './runtime-client.js';
import {runProgressView,completedCalls} from './progress-view.js';
const metric=m=>m?`${m.passed} / ${m.total} (${Math.round(m.score*100)}%)`:'尚未評估';
const button=(attr,text,disabled=false)=>`<button class="button secondary" ${attr} ${disabled?'disabled':''}>${text}</button>`;
export function llmView(runtime){
 const workspace=runtime.data?.llm,run=runtime.selectedLlmRun||workspace?.latestRun,p=run?.llmProgress,result=run?.llmResult;
 const active=runtime.data?.latestRun&&['queued','running'].includes(runtime.data.latestRun.status);
 const stale=!!runtime.error||!workspace||!runtime.capabilities,disabled=stale||runtime.actionBusy;
 const approved=workspace?.versions.some(v=>v.runId===run?.id);
 const eligible=!disabled&&run?.status==='completed'&&result?.eligible&&!approved&&workspace.activeVersionId===run.llmConfig.baseline.id;
 const base=run?.llmConfig.baseline.skill||workspace?.active.skill,candidate=p?.candidates?.find(c=>c.id==='C1');
 return `<div class="page-heading"><div><p class="eyebrow">LLM SKILL EVOLUTION · POLLING</p><h1>LLM 技能實驗</h1><p>真實模型執行、訓練反思、驗證選擇與人工版本審核。</p></div><div class="actions">${button('data-live-refresh','↻ 更新狀態')}<button class="button primary" data-llm-start ${disabled||active?'disabled':''}>開始 LLM 技能演化</button></div></div>
 <div class="demo-banner"><span class="info-icon">i</span><div><strong>實際 Ollama 模型流程 · 自建反思搜尋</strong><span>每輪產生一個候選，只改 Skill 本文。未接入 nanobot／GEPA SDK；規則技能實驗與模型技能版本分開保存。</span></div><a href="#integrations">設定模型 ↗</a></div>
 ${stale?`<div class="error-banner spaced">${esc(runtime.error||'等待本機模型技能服務')}。請使用 WSL localhost GUI；過期快照禁止提交與核准。</div>`:''}
 <section class="card spaced"><div class="card-heading"><div><h2>執行設定</h2><p>使用「框架整合」已儲存的模型；提交時凍結設定，不會先跑連線診斷。</p></div><a href="#runtime">查看角色、PID 與 log ↗</a></div><div class="actions card-actions"><label>資料分割<select data-llm-profile ${active?'disabled':''}><option value="smoke" ${runtime.llmProfile==='smoke'?'selected':''}>Smoke：3 / 2 / 2，最多 15 次模型呼叫</option><option value="full" ${runtime.llmProfile==='full'?'selected':''}>Full：20 / 10 / 20，最多 101 次模型呼叫</option></select></label><label>整輪時間上限（秒）<input type="number" data-llm-seconds min="60" max="7200" value="${runtime.llmSeconds||900}" ${active?'disabled':''}></label><label>單次模型時間上限（秒）<input type="number" data-llm-call-seconds min="10" max="3600" value="${runtime.llmCallSeconds||120}" ${active?'disabled':''}></label>${button('data-live-toggle',runtime.enabled?'暫停 polling':'繼續 polling')}${run&&['queued','running'].includes(run.status)?button(`data-live-cancel="${esc(run.id)}"`,'取消這輪'):''}</div><p class="body-copy">最近成功 polling：${esc(runtime.lastSuccess||'尚無')} · ${runtime.pollCount} 次 · ${runtime.enabled?'持續更新':'已暫停'}。單次上限會受已儲存的模型逾時設定與整輪剩餘時間限制。Smoke 僅驗證流程；分數限於這組小型測試題。</p></section>
 ${runProgressView(runtime,run)}
 <div class="metrics spaced"><article class="metric"><div>基準驗證</div><strong class="runtime-metric">${esc(metric(p?.candidates?.[0]?.validation))}</strong></article><article class="metric"><div>候選驗證</div><strong class="runtime-metric">${esc(metric(candidate?.validation))}</strong></article><article class="metric"><div>已完成模型呼叫</div><strong class="runtime-metric">${completedCalls(p)} / ${run?.llmConfig.callBudget||'—'}</strong><small>${esc(p?.lastCall?`已送出 ${p.calls} 次 · ${p.lastCall.kind} · ${p.lastCall.status}`:'尚未呼叫')}</small></article><article class="metric"><div>流程狀態</div><strong class="runtime-metric">${esc(run?(stale?'快照過期':LIVE_STATUSES[run.status]):'尚未開始')}</strong><small>${esc(p?.phase||'等待提交')}</small></article></div>
 <section class="card spaced"><div class="card-heading"><div><h2>技能變更檢閱</h2><p>${esc(run?.llmConfig.provider.config.model||'尚未提交模型實驗')} · ${esc(run?.llmConfig.provider.endpoint||'依已儲存設定')} · ${esc(result?.decision||'等待實際評估')}</p></div>${button(`data-llm-approve="${esc(run?.id||'')}"`,approved?'已建立版本':'核准並啟用候選',!eligible)}</div><div class="diff"><div><div class="diff-heading">基準</div><pre>${esc(base?.body||'等待技能資料')}</pre></div><div><div class="diff-heading accent">候選</div><pre>${esc(candidate?.skill.body||'等待訓練反思')}</pre></div></div><div class="small-notice">${result?`保留測試：基準 ${metric(result.heldout.baseline)}；選定版本 ${metric(result.heldout.selected)}。${result.eligible?'通過改善門檻，仍需人工核准。':'保留基準；沒有改善也是有效實驗結果。'}`:'驗證改善且保留測試不退步，才開放人工核准。Reviewer 從原始模型回應重算分數，不重新呼叫模型。'}<br>重新執行模型可能得到不同答案；本輪證據僅代表這次觀測。</div></section>
 <section class="card spaced"><div class="card-heading"><div><h2>模型技能版本與回復</h2><p>目前 ${esc(workspace?.active.label||'—')} · revision ${workspace?.revision||'—'}；下一次模型實驗採用啟用版本。</p></div></div>${(workspace?.versions||[]).map(v=>`<div class="release-row"><span class="version-icon">◇</span><div><h3>${esc(v.label)} · ${esc(v.skill.hash.slice(0,12))}</h3><p>${esc(v.runId||'初始基準')}</p></div>${button(`data-llm-export="${esc(v.id)}"`,'↓ SKILL.md',disabled)}${button(`data-llm-activate="${esc(v.id)}"`,workspace.activeVersionId===v.id?'使用中':'切換版本',disabled||workspace.activeVersionId===v.id)}</div>`).join('')}</section>
 ${p?.trainingFailures?.length?`<section class="card spaced"><div class="card-heading"><h2>基準訓練失敗案例</h2></div><div class="table-wrap"><table><thead><tr><th>Task</th><th>輸入</th><th>模型輸出</th><th>預期</th></tr></thead><tbody>${p.trainingFailures.map(r=>`<tr><td>${esc(r.taskId)}</td><td><code>${esc(JSON.stringify(r.input))}</code></td><td><code>${esc(r.formatError||JSON.stringify(r.output))}</code></td><td><code>${esc(JSON.stringify(r.expected))}</code></td></tr>`).join('')}</tbody></table></div></section>`:''}
 ${run?`<section class="card spaced"><div class="card-heading"><div><h2>執行證據</h2><p>${esc(run.id)} · 模型設定 revision ${run.llmConfig.provider.revision} · 最多 ${run.llmConfig.maxOutputTokens} 個設定輸出 tokens · ${run.llmConfig.maxSeconds} 秒</p></div></div><p class="body-copy">完整 requests、原始 responses、usage 與耗時存於 .local/runs/。API 預覽超過 200,000 字元會標記 truncated；完整檔案仍保存在 D 槽。</p><div class="artifact-links">${run.artifacts.map(n=>`<a target="_blank" rel="noreferrer" href="/api/v1/runtime/runs/${encodeURIComponent(run.id)}/artifacts/${encodeURIComponent(n)}">${esc(n)} ↗</a>`).join('')||'流程結束後列出產物'}</div></section>`:''}
 <section class="card spaced"><div class="card-heading"><h2>近期模型實驗</h2>${button('data-llm-select=""','查看最新')}</div><div class="table-wrap"><table><thead><tr><th>Run</th><th>狀態</th><th>建立時間</th></tr></thead><tbody>${(workspace?.runs||[]).map(r=>`<tr><td><button class="text-button" data-llm-select="${esc(r.id)}">${esc(r.id)}</button></td><td>${esc(LIVE_STATUSES[r.status])}</td><td>${esc(r.createdAt)}</td></tr>`).join('')||'<tr><td colspan="3">尚無模型實驗</td></tr>'}</tbody></table></div></section>`;
}
